          step: { enum: STEPS },
          file: { type: "string" },
          line: { type: "integer", minimum: 1 },
          end_line: { type: "integer", minimum: 1 },
          title: { type: "string" },
          body: { type: "string" },
          suggestion: { type: "string" }
